<?php use App\Models\Modules;use App\Core\DB; ?>
<div class="page-heading"><div><div class="eyebrow">YOUR WEBSITE CONTENT</div><h1><?=e($def['label'])?></h1><p><?=number_format($total)?> record<?=$total===1?'':'s'?> · All changes connect directly to your website.</p></div><div class="actions"><?php if(in_array($module,['categories','brands','subcategories'],true)):?><a class="button secondary" href="<?=e(cms_url('/admin/catalogue-import/'.$module))?>">↑ Import CSV</a><?php endif?><?php if($module==='products'&&App\Services\Auth::can('media')):?><a class="button secondary" href="<?=e(cms_url('/admin/products/bulk-images'))?>">Bulk Images</a><?php endif?><?php if(in_array($module,['enquiries','products'],true)):?><a class="button secondary" href="<?=e(cms_url('/admin/'.$module.'/export'))?>">↓ Export CSV</a><?php endif?><?php if($module==='gallery_items'):?><a class="button secondary" href="<?=e(cms_url('/admin/gallery_albums'))?>">Manage albums</a><?php endif?><?php if(empty($def['no_create'])&&empty($def['read_only'])):?><a class="button" href="<?=e(cms_url('/admin/'.$module.'/new'.(request()->query()?'?'.http_build_query(array_intersect_key(request()->query(),$def['fields'])):'')))?>">＋ Add new</a><?php endif?></div></div>
<?php if(in_array($module,['gallery_items','product_images'],true))cms_view('admin/bulk-images',compact('module'));?><section class="panel"><form class="list-toolbar" method="get"><label class="search-field"><span>⌕</span><input type="search" name="q" placeholder="Search <?=e(strtolower($def['label']))?>…" aria-label="Search" value="<?=e($q)?>"></label><?php foreach($def['fields'] as $key=>$field):if($key==='status'):?><select name="status" aria-label="Filter by status"><option value="">All statuses</option><?php foreach($field['options'] as $value=>$label):?><option value="<?=e($value)?>" <?=(request()->query()['status']??'')===$value?'selected':''?>><?=e($label)?></option><?php endforeach?></select><?php elseif($field['type']==='relation'&&($field['table']??'')!=='media_files'):?><select name="<?=e($key)?>" aria-label="<?=e($field['label'])?>"><option value="">All <?=e(strtolower($field['label']))?></option><?php foreach(DB::all('SELECT id,`'.Modules::labelField($field['table']).'` AS label FROM `'.$field['table'].'` ORDER BY label LIMIT 1000') as $option):?><option value="<?=$option['id']?>" <?=(string)(request()->query()[$key]??'')===(string)$option['id']?'selected':''?>><?=e($option['label'])?></option><?php endforeach?></select><?php endif;endforeach?><?php if($module==='enquiries'):?><label>From <input type="date" name="from" value="<?=e(request()->query()['from']??'')?>"></label><label>To <input type="date" name="to" value="<?=e(request()->query()['to']??'')?>"></label><?php endif?><button class="button secondary" type="submit">Filter</button><a class="text-link" href="<?=e(cms_url('/admin/'.$module))?>">Reset</a></form>
<?php if($rows):?><div class="table-wrap"><table><thead><tr><th><?=($module==='admin_activity_logs')?'Activity':'Name'?></th><?php if(isset($def['fields']['image_id'])):?><th>Image</th><?php endif?><?php if(isset($def['fields']['slug'])):?><th>Web address</th><?php endif?><?php if(isset($def['fields']['status'])||isset($def['fields']['is_active'])):?><th>Status</th><?php endif?><?php if($module==='enquiries'):?><th>Email</th><th>Notifications</th><?php endif?><th>Updated (IST)</th><th class="align-right">Actions</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><strong><?php if(empty($def['read_only'])):?><a href="<?=e(cms_url('/admin/'.$module.'/'.$row['id']))?>"><?=e($row[Modules::labelField($module)])?></a><?php else:?><?=e($row['summary'])?><?php endif?></strong><?php if(in_array($row['id'],$drafts)):?><small class="draft-note">● Unpublished draft changes</small><?php endif?><?php if($module==='admin_activity_logs'):?><small><?=e($row['action'].' · '.$row['entity'].' #'.$row['entity_id'])?></small><?php endif?></td><?php if(isset($def['fields']['image_id'])):?><td><?=media_img($row['image_id'],$row['title'],'table-image')?></td><?php endif?><?php if(isset($def['fields']['slug'])):?><td class="muted">/<?=e($row['slug'])?>/</td><?php endif?><?php if(isset($def['fields']['status'])||isset($def['fields']['is_active'])):$status=$row['status']??($row['is_active']?'published':'unpublished');?><td><span class="status <?=e($status)?>"><?=e(ucfirst($status))?></span></td><?php endif?><?php if($module==='enquiries'):?><td><?=e($row['email'])?></td><td><?=e($row['notification_status'])?></td><?php endif?><td class="muted"><?=e(ist_datetime($row['updated_at']))?></td><td><div class="row-actions"><?php if(empty($def['read_only'])):?><a class="button tiny secondary" href="<?=e(cms_url('/admin/'.$module.'/'.$row['id']))?>">Edit</a><?php if(empty($def['no_duplicate'])):?><form method="post" action="<?=e(cms_url('/admin/'.$module.'/'.$row['id'].'/duplicate'))?>"><?=csrf_field()?><button class="icon-button" title="Duplicate" aria-label="Duplicate <?=e($row[Modules::labelField($module)])?>">⧉</button></form><?php endif?><form method="post" action="<?=e(cms_url('/admin/'.$module.'/'.$row['id'].'/delete'))?>" data-confirm="Delete this record? Related records may prevent deletion."><?=csrf_field()?><button class="icon-button danger-text" title="Delete" aria-label="Delete <?=e($row[Modules::labelField($module)])?>">×</button></form><?php endif?></div></td></tr><?php endforeach?></tbody></table></div><?php else:?><div class="empty-state"><span>◇</span><h2><?= $q?'No matching records':'Your next update starts here'?></h2><p><?=$q?'Try another search or clear your filters.':'Add your first record when you are ready. No business data has been fabricated.'?></p><?php if(empty($def['no_create'])&&empty($def['read_only'])):?><a class="button" href="<?=e(cms_url('/admin/'.$module.'/new'))?>">＋ Add new</a><?php endif?></div><?php endif?>
<?php cms_view('admin/pagination',compact('total','page','perPage'));?></section>
